SELECT 'jobs_total' as tabela, COUNT(*)::text as total FROM jobs UNION ALL SELECT 'jobs_completed', COUNT(*)::text FROM jobs WHERE status='completed' UNION ALL SELECT 'jobs_failed', COUNT(*)::text FROM jobs WHERE status='failed_permanent' UNION ALL SELECT 'jobs_pending', COUNT(*)::text FROM jobs WHERE status='pending' UNION ALL SELECT 'jobs_running', COUNT(*)::text FROM jobs WHERE status='running' UNION ALL SELECT 'lead_inventory_total', COUNT(*)::text FROM lead_inventory UNION ALL SELECT 'leads_total', COUNT(*)::text FROM leads;